/** 正規捕球の三振候補。閉schemaから再現生成。真正性/T2は別検査。 */
export type CanonicalUnsigned = string & {readonly __CanonicalUnsigned: unique symbol};
export type CanonicalPositive = string & {readonly __CanonicalPositive: unique symbol};
export type Score = Readonly<{readonly "home": CanonicalUnsigned; readonly "away": CanonicalUnsigned}>;
export type StateFields = Readonly<{readonly "state.half": ("top" | "bottom"); readonly "state.count.strikes": CanonicalUnsigned; readonly "state.count.balls": CanonicalUnsigned; readonly "state.outs": CanonicalUnsigned; readonly "state.runners": ("empty" | "first" | "second" | "third" | "first-second" | "first-third" | "second-third" | "first-second-third"); readonly "state.battingOrder": CanonicalUnsigned; readonly "state.tiebreakActive": boolean; readonly "state.gameEnded": boolean; readonly "state.inning": CanonicalPositive; readonly "state.score": Score}>;
export type Scoreboard = Readonly<{readonly "inningScores": Score; readonly "hits": CanonicalUnsigned; readonly "errors": CanonicalUnsigned; readonly "strikeouts": CanonicalUnsigned; readonly "walks": CanonicalUnsigned}>;
export type Snapshot = Readonly<{readonly "stateFields": StateFields; readonly "scoreboard": Scoreboard; readonly "battingOrderBySide": BattingOrderBySide}>;
export type StatFlags = Readonly<{readonly "投球回算入アウト": boolean; readonly "投球数": boolean; readonly "奪三振": boolean; readonly "与四球": boolean; readonly "与死球": boolean; readonly "被安打": boolean; readonly "被本塁打": boolean; readonly "失点": boolean; readonly "失策": boolean; readonly "打席": boolean; readonly "打数": boolean; readonly "安打": boolean; readonly "本塁打": boolean; readonly "塁打": boolean; readonly "犠打": boolean; readonly "犠飛": boolean; readonly "四球": boolean; readonly "死球": boolean; readonly "三振": boolean; readonly "打撃妨害出塁": boolean; readonly "走塁妨害出塁": boolean; readonly "得点": boolean; readonly "打点": boolean}>;
export type StateDifference = Readonly<{readonly "state.half"?: Readonly<{readonly "before": ("top" | "bottom"); readonly "after": ("top" | "bottom")}>; readonly "state.count.strikes"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "state.count.balls"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "state.outs"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "state.runners"?: Readonly<{readonly "before": ("empty" | "first" | "second" | "third" | "first-second" | "first-third" | "second-third" | "first-second-third"); readonly "after": ("empty" | "first" | "second" | "third" | "first-second" | "first-third" | "second-third" | "first-second-third")}>; readonly "state.battingOrder"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "state.tiebreakActive"?: Readonly<{readonly "before": boolean; readonly "after": boolean}>; readonly "state.gameEnded"?: Readonly<{readonly "before": boolean; readonly "after": boolean}>; readonly "state.inning"?: Readonly<{readonly "before": CanonicalPositive; readonly "after": CanonicalPositive}>; readonly "state.score"?: Readonly<{readonly "before": Score; readonly "after": Score}>}>;
export type ScoreboardDifference = Readonly<{readonly "inningScores"?: Readonly<{readonly "before": Score; readonly "after": Score}>; readonly "hits"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "errors"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "strikeouts"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "walks"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>}>;
export type HistoryEntry = Readonly<{readonly "kind": "confirmed-play"; readonly "difference": Readonly<{readonly "stateFields": StateDifference; readonly "scoreboard": ScoreboardDifference; readonly "statFlags": StatFlags; readonly "battingOrderBySide"?: CursorDifference}>}>;
export type BattingOrderBySide = Readonly<{readonly "away": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9"); readonly "home": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9")}>;
export type CursorDifference = Readonly<{readonly "away"?: Readonly<{readonly "before": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9"); readonly "after": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9")}>; readonly "home"?: Readonly<{readonly "before": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9"); readonly "after": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9")}>}>;
export type StrikeoutPitchRequest = Readonly<{readonly "eventKind": "batting-result"; readonly "resultId": ("batting-result.called-strikeout" | "batting-result.swinging-strikeout"); readonly "pitchEventKind": "pitch-event"; readonly "before": Readonly<{readonly "stateFields": Readonly<{readonly "state.half": ("top" | "bottom"); readonly "state.count.strikes": "2"; readonly "state.count.balls": ("0" | "1" | "2" | "3"); readonly "state.outs": ("0" | "1" | "2"); readonly "state.runners": ("empty" | "first" | "second" | "third" | "first-second" | "first-third" | "second-third" | "first-second-third"); readonly "state.battingOrder": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9"); readonly "state.tiebreakActive": boolean; readonly "state.gameEnded": false; readonly "state.inning": CanonicalPositive; readonly "state.score": Score}>; readonly "scoreboard": Scoreboard; readonly "battingOrderBySide": BattingOrderBySide}>; readonly "history": Readonly<{readonly "stack": readonly (HistoryEntry)[]}>}>;
export type StrikeoutValue = Readonly<{readonly "countEffect": Readonly<{readonly "strikes": Readonly<{readonly "kind": "reset"}>; readonly "balls": Readonly<{readonly "kind": "reset"}>}>; readonly "plateAppearanceEnded": true; readonly "batterDestination": Readonly<{readonly "kind": "out"}>; readonly "runnerDefaultAdvance": Readonly<{readonly "first": Readonly<{readonly "modality": ("hold" | "not-applicable"); readonly "destination": null}>; readonly "second": Readonly<{readonly "modality": ("hold" | "not-applicable"); readonly "destination": null}>; readonly "third": Readonly<{readonly "modality": ("hold" | "not-applicable"); readonly "destination": null}>}>; readonly "outEffect": Readonly<{readonly "count": "1"; readonly "targets": readonly ["batter"]}>; readonly "statFlags": Readonly<{readonly "投球回算入アウト": true; readonly "投球数": true; readonly "奪三振": true; readonly "与四球": false; readonly "与死球": false; readonly "被安打": false; readonly "被本塁打": false; readonly "失点": false; readonly "失策": false; readonly "打席": true; readonly "打数": true; readonly "安打": false; readonly "本塁打": false; readonly "塁打": false; readonly "犠打": false; readonly "犠飛": false; readonly "四球": false; readonly "死球": false; readonly "三振": true; readonly "打撃妨害出塁": false; readonly "走塁妨害出塁": false; readonly "得点": false; readonly "打点": false}>; readonly "after": AfterSnapshot; readonly "historyContext": readonly (HistoryEntry)[]}>;
export type SuccessResponse = Readonly<{readonly "ok": true; readonly "value": StrikeoutValue}>;
export type FailureResponse = Readonly<{readonly "ok": false; readonly "error": Readonly<{readonly "code": ("INVALID_JSON" | "INVALID_REQUEST" | "INVALID_DECIMAL_INTEGER" | "UNSUPPORTED_T1_SCOPE")}>}>;
export type StrikeoutPitchResponse = (SuccessResponse | FailureResponse);
export type AfterSnapshot = Readonly<{readonly "stateFields": Readonly<{readonly "state.half": ("top" | "bottom"); readonly "state.count.strikes": "0"; readonly "state.count.balls": "0"; readonly "state.outs": ("0" | "1" | "2"); readonly "state.runners": ("empty" | "first" | "second" | "third" | "first-second" | "first-third" | "second-third" | "first-second-third"); readonly "state.battingOrder": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9"); readonly "state.tiebreakActive": boolean; readonly "state.gameEnded": false; readonly "state.inning": CanonicalPositive; readonly "state.score": Score}>; readonly "scoreboard": Scoreboard; readonly "battingOrderBySide": BattingOrderBySide}>;
